printf '\n!.env.example\n' >> .gitignore &&
cat > .env.example <<'EOF'
# Resend (https://resend.com) — transactional email
RESEND_API_KEY=re_placeholder
# Must be on a domain verified in Resend (or onboarding@resend.dev while testing)
RESEND_FROM_EMAIL=Notely <hello@example.com>
# Public base URL used to build links in emails
APP_URL=http://localhost:3000
EOF
cat > src/lib/resend.ts <<'EOF'
import { Resend } from "resend";

let client: Resend | undefined;

// Lazy so the app still builds and runs without credentials.
export function getResend(): Resend | undefined {
  const key = process.env.RESEND_API_KEY;
  if (!key) return undefined;
  client ??= new Resend(key);
  return client;
}
EOF
cat > src/lib/email.ts <<'EOF'
import { getResend } from "@/lib/resend";

const escapeHtml = (s: string) =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

const appUrl = () => process.env.APP_URL ?? "http://localhost:3000";

// Never throws: a failed email must not break the request that triggered it.
async function send(to: string, subject: string, text: string, html: string) {
  const resend = getResend();
  const from = process.env.RESEND_FROM_EMAIL;
  if (!resend || !from) {
    console.warn(`[email] RESEND_API_KEY/RESEND_FROM_EMAIL not set; skipping "${subject}"`);
    return;
  }
  try {
    const { error } = await resend.emails.send({ from, to, subject, text, html });
    if (error) console.error(`[email] "${subject}" failed: ${error.name}: ${error.message}`);
  } catch (err) {
    console.error(`[email] "${subject}" failed`, err);
  }
}

export async function sendWelcomeEmail(user: { email: string; name: string }) {
  const url = `${appUrl()}/dashboard`;
  await send(
    user.email,
    "Welcome to Notely",
    `Hi ${user.name},\n\nWelcome to Notely! Get started: ${url}`,
    `<p>Hi ${escapeHtml(user.name)},</p><p>Welcome to Notely! <a href="${url}">Open your dashboard</a>.</p>`,
  );
}

export async function sendPasswordResetEmail(
  user: { email: string; name: string },
  token: string,
) {
  const url = `${appUrl()}/reset-password?token=${encodeURIComponent(token)}`;
  await send(
    user.email,
    "Reset your Notely password",
    `Hi ${user.name},\n\nReset your password: ${url}\n\nThis link expires in 1 hour. If you didn't ask for it, ignore this email.`,
    `<p>Hi ${escapeHtml(user.name)},</p><p><a href="${url}">Reset your password</a>. This link expires in 1 hour.</p><p>If you didn't ask for it, ignore this email.</p>`,
  );
}
EOF
python3 - <<'EOF'
p='src/lib/users.ts'
s=open(p).read()
s='import { createHash, randomBytes } from "node:crypto";\nimport { sendPasswordResetEmail, sendWelcomeEmail } from "@/lib/email";\n\n'+s
s+='''
export async function createUser(input: { email: string; name: string }): Promise<User> {
  const user: User = {
    id: String(users.length + 1),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  await sendWelcomeEmail(user);
  return user;
}

const RESET_TTL_MS = 60 * 60 * 1000;
// token hash -> reset request; only hashes are stored.
const resetTokens = new Map<string, { userId: string; expiresAt: number }>();

const hashToken = (token: string) => createHash("sha256").update(token).digest("hex");

// Silently does nothing for unknown emails so callers can't probe for accounts.
export async function requestPasswordReset(email: string): Promise<void> {
  const user = users.find((u) => u.email.toLowerCase() === email.toLowerCase());
  if (!user) return;
  const token = randomBytes(32).toString("base64url");
  resetTokens.set(hashToken(token), { userId: user.id, expiresAt: Date.now() + RESET_TTL_MS });
  await sendPasswordResetEmail(user, token);
}

// Single-use: returns the user id for a valid token and consumes it.
export async function consumePasswordResetToken(token: string): Promise<string | undefined> {
  const key = hashToken(token);
  const entry = resetTokens.get(key);
  resetTokens.delete(key);
  if (!entry || entry.expiresAt < Date.now()) return undefined;
  return entry.userId;
}
'''
open(p,'w').write(s)
EOF
